@custom-variant dark (&:where(.dark, .dark *));

:root {
  --bg: #111117;
  --bg-soft: #17171e;
  --ivory: #F2F0EB;
  --violet: #A58AFF;
  --cobalt: #5367F9;
  --lilac: #D8CFF2;
  --muted: #96939F;
  --line: rgba(242, 240, 235, 0.20);
  --line-strong: rgba(242, 240, 235, 0.38);
  --section-pad-x: clamp(22px, 3vw, 58px);
  --header-h: clamp(68px, 7vw, 104px);
  --ease-editorial: cubic-bezier(0.22, 1, 0.36, 1);

  --font-display: var(--font-cormorant-garamond), 'Cormorant Garamond', var(--font-bodoni-moda), 'Bodoni Moda', Georgia, serif;
  --font-sans: var(--font-dm-sans), 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  background-color: var(--bg);
  color: var(--ivory);
  font-family: var(--font-sans);
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

body {
  background-color: var(--bg);
  color: var(--ivory);
  margin: 0;
  padding: 0;
  overflow-x: hidden;
  position: relative;
}

/* Continuous subtle editorial print grain overlay across all sections */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 45;
  opacity: 0.032;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

/* Editorial Display Typography */
.font-editorial {
  font-family: var(--font-display);
  font-feature-settings: "liga" 1, "kern" 1;
}

.font-grotesk {
  font-family: var(--font-sans);
}

/* Oversized statement scale matching 16:9 references */
.zeno-display-hero {
  font-family: var(--font-display);
  font-size: clamp(3.3rem, 7.1vw, 8.2rem);
  line-height: 0.89;
  letter-spacing: -0.022em;
  font-weight: 600;
}

.zeno-display-section {
  font-family: var(--font-display);
  font-size: clamp(3.1rem, 6.6vw, 7.6rem);
  line-height: 0.90;
  letter-spacing: -0.022em;
  font-weight: 600;
}

.zeno-display-work {
  font-family: var(--font-display);
  font-size: clamp(2.85rem, 6.0vw, 6.9rem);
  line-height: 0.91;
  letter-spacing: -0.02em;
  font-weight: 600;
}

/* Expressive Violet Italic Accent with subtle registration echo */
.zeno-accent-italic {
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 600;
  color: var(--violet);
  letter-spacing: -0.01em;
  text-shadow: 3px 2px 0px rgba(165, 138, 255, 0.2), -1.5px -1px 0px rgba(83, 103, 249, 0.18);
}

/* Transparent Cutout Contour Shadows & 3D Depth Layering */
.cutout-shadow-hero {
  filter: drop-shadow(0 28px 52px rgba(0, 0, 0, 0.78))
          drop-shadow(0 6px 18px rgba(83, 103, 249, 0.16));
  will-change: transform;
}

.cutout-shadow-card {
  filter: drop-shadow(0 18px 34px rgba(0, 0, 0, 0.76))
          drop-shadow(0 4px 10px rgba(0, 0, 0, 0.55));
  will-change: transform;
}

.cutout-shadow-card-active {
  filter: drop-shadow(0 24px 44px rgba(0, 0, 0, 0.86))
          drop-shadow(0 0 26px rgba(165, 138, 255, 0.22));
  will-change: transform;
}

.cutout-shadow-world {
  filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.22));
  will-change: transform;
}

.perspective-stage {
  perspective: 1200px;
}

/* Focus accessibility ring */
.zeno-focus:focus-visible {
  outline: 2px solid var(--violet);
  outline-offset: 4px;
}

/* Vertical archive micro-labels */
.writing-vertical {
  writing-mode: vertical-rl;
  text-orientation: mixed;
}

